{"path":"chat_app/src/bin/server.rs","content":"use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};
use std::thread;

type Clients = Arc<Mutex<HashMap<usize, TcpStream>>>;

fn main() {
    let listener = TcpListener::bind("127.0.0.1:7878").expect("Failed to bind to port 7878");
    println!("=== Chat Server started on 127.0.0.1:7878 ===");
    println!("Waiting for clients to connect...\n");

    let clients: Clients = Arc::new(Mutex::new(HashMap::new()));
    let mut next_id: usize = 0;

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let id = next_id;
                next_id += 1;
                println!("[Server] Client {} connected from {}", id, stream.peer_addr().unwrap());

                // Add client to the map
                clients.lock().unwrap().insert(id, stream.try_clone().unwrap());

                // Broadcast join message
                broadcast(&clients, id, &format!("** Client {} joined the chat! **", id));

                // Spawn a thread to handle this client
                let clients_clone = Arc::clone(&clients);
                thread::spawn(move || {
                    handle_client(id, stream, &clients_clone);
                });
            }
            Err(e) => {
                eprintln!("[Server] Connection failed: {}", e);
            }
        }
    }
}

fn handle_client(id: usize, stream: TcpStream, clients: &Clients) {
    let reader = BufReader::new(stream.try_clone().unwrap());
    for line in reader.lines() {
        match line {
            Ok(msg) => {
                if msg == "/quit" {
                    println!("[Server] Client {} disconnected", id);
                    broadcast(clients, id, &format!("** Client {} left the chat! **", id));
                    clients.lock().unwrap().remove(&id);
                    break;
                }
                println!("[Server] Client {}: {}", id, msg);
                broadcast(clients, id, &format!("[Client {}]: {}", id, msg));
            }
            Err(_) => {
                println!("[Server] Client {} disconnected unexpectedly", id);
                clients.lock().unwrap().remove(&id);
                broadcast(clients, id, &format!("** Client {} left the chat! **", id));
                break;
            }
        }
    }
}

fn broadcast(clients: &Clients, sender_id: usize, message: &str) {
    let mut clients_lock = clients.lock().unwrap();
    let mut to_remove = Vec::new();

    for (&id, stream) in clients_lock.iter_mut() {
        if id != sender_id {
            if let Err(e) = writeln!(stream, "{}", message) {
                eprintln!("[Server] Failed to send to client {}: {}", id, e);
                to_remove.push(id);
            }
        }
    }

    for id in to_remove {
        clients_lock.remove(&id);
    }
}
"}

{"path":"chat_app/src/bin/client.rs","content":"use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let stream = TcpStream::connect("127.0.0.1:7878").expect("Failed to connect to server");
    println!("=== Connected to chat server at 127.0.0.1:7878 ===");
    println!("Type messages and press Enter to send.");
    println!("Type /quit to disconnect.\n");

    let stream_clone = stream.try_clone().expect("Failed to clone stream");
    let received = Arc::new(Mutex::new(String::new()));

    // Thread to read messages from the server
    let received_clone = Arc::clone(&received);
    thread::spawn(move || {
        let reader = BufReader::new(stream_clone);
        for line in reader.lines() {
            match line {
                Ok(msg) => {
                    println!("{}", msg);
                    let mut r = received_clone.lock().unwrap();
                    r.clear();
                    r.push_str(&msg);
                }
                Err(_) => break,
            }
        }
    });

    // Main thread reads from stdin and sends to server
    let mut stdout = std::io::stdout();
    loop {
        let mut input = String::new();
        std::io::stdin().read_line(&mut input).expect("Failed to read from stdin");
        let input = input.trim();

        if input.is_empty() {
            continue;
        }

        if let Err(e) = writeln!(&stream, "{}", input) {
            eprintln!("Failed to send message: {}", e);
            break;
        }

        if input == "/quit" {
            println!("Disconnecting...");
            break;
        }

        // Small delay to allow server echo/broadcast to arrive
        std::thread::sleep(std::time::Duration::from_millis(50));
        let _ = stdout.flush();
    }

    println!("Goodbye!");
}
"}

