        package = Package(weight_kg=1.234, length_cm=10, width_cm=10, height_cm=10)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 6.17


class TestEdgeCases:
    """Test edge cases that should work correctly."""

    def test_exact_overweight_threshold(self):
        """Test at exactly 30kg (no overweight surcharge)."""
        package = Package(weight_kg=30.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 150.0

