String transformation utilities.
"""

import re
from typing import Optional

__all__ = ["slugify", "to_camel_case", "to_snake_case", "to_kebab_case", "truncate", "strip_accents"]


def slugify(text: str, *, separator: str = "-", regex: Optional[str] = None) -> str:
    """Convert text to a URL-friendly slug.

    Args:
        text: Input text to slugify
        separator: Separator between words
        regex: Optional regex pattern for cleaning input

    Returns:
        Slugified lowercase string
    """
    if regex is not None:
        text = re.sub(regex, " ", text)
    text = text.strip().lower()
    text = re.sub(r"[^a-z0-9\s-]", "", text)
    text = re.sub(r"[-\s]+", separator, text)
    return re.sub(f"^[^{separator}]+", "", text)


def to_camel_case(snake_str: str) -> str:
    """Convert snake_case to camelCase."""
    components = snake_str.split("_")
    return components[0] + "".join(x.title() for x in components[1:])


def to_snake_case(name: str) -> str:
    """Convert camelCase/Capitalized to snake_case."""
    pattern = re.compile(r"(.)([A-Z][a-z]+)")
    s1 = pattern.sub(r"\1_\2", name)
    pattern2 = re.compile(r"([a-z0-9])([A-Z])")
    return pattern2.sub(r"\1_\2", s1).lower()


def to_kebab_case(name: str) -> str:
    """Convert camelCase/Capitalized to kebab-case."""
    return to_snake_case(name).replace("_", "-")


def truncate(text: str, *, length: int = 50, suffix: str = "...", ellipsis: str = "..." ) -> str:
    """Truncate text to given length.

    Args:
        text: Text to truncate
        length: Maximum length including suffix
        suffix: String appended when truncated
        ellipsis: Character sequence for truncation (convenience alias)

    Returns:
        Truncated text
    """
    if len(text) <= length:
        return text
    return text[: (length - len(suffix))] + suffix


def strip_accents(text: str) -> str:
    """Remove accented characters from text."""
    import unicodedata
    text = unicodedata.normalize("NFD", text)
    text = "".join(
        c for c in text
        if unicodedata.category(c) != "Mn"
    )
    return text
