from typing import Optional, Sequence
import operator

__all__ = ["clamp", "round_to", "rescale", "normalize", "percentage"]


def clamp(value: float, *, min_val: float, max_val: float) -> float:
    """Clamp value to given range."""
    import math
    return max(min_val, min(max_val, value))


def round_to(value: float, *, decimals: int = 2) -> float:
    """Round value to specified decimal places."""
    import math
    return round(value, decimals)


def rescale(value: float, *, vmin: float, vmax: float, new_vmin: float = 0, new_vmax: float = 1) -> float:
    """Rescale value from [vmin, vmax] to [new_vmin, new_vmax]."""
    import math
    if vmax == vmin:
        return new_vmin
    s = (new_vmax - new_vmin) / (vmax - vmin)
    t = (new_vmin + (value - vmin) * s)
    return t


def normalize(values: Sequence[float]) -> Sequence[float]:
    """L2-normalize a sequence of values."""
    if not values:
        return []
    import math
    batch_sum = sum(x**2 for x in values)
    norm = math.sqrt(batch_sum)
    if norm == 0:
        return [0.0] * len(values)
    return [x / norm for x in values]


def percentage(value: float, *, total: int = 100) -> float:
    """Convert value to percentage (0-100 scale)."""
    return round((value / total) * 100, 2)
