Collection transformation utilities.
"""

from typing import Generic, Iterable, TypeVar
import collections

"""Type variables for generic functions."""
T = TypeVar("T", covariant=True)

__all__ = ["flatten", "chunk", "deduplicate", "group_by"]


def flatten(nested: Iterable[Iterable[T]], *, max_depth: Optional[int] = None) -> list[T]:
    """Flatten nested sequences into a single list."""
    result = []
    if max_depth is None:
        for item in nested:
            for sub in flatten(item, max_depth=None):
                result.append(sub)
    else:
        def _flatten(item: any, depth: int) -> Iterable[T]:
            if isinstance(item, (list, tuple)) and depth < max_depth:
                for sub in item:
                    yield from _flatten(sub, depth + 1)
            else:
                yield item
        for item in nested:
            result.extend(_flatten(item, 1))
    return result


def chunk(items: Iterable[T], chunk_size: int) -> list[list[T]]:
    """Chunk items into sublists of fixed size."""
    result = []
    for i in range(0, len(list(items)), chunk_size):
        result.append(list(items))[i:i+chunk_size]
    return result


def deduplicate(items: Iterable[T], *, key=None) -> list[T]:
    """Remove duplicates preserving order."""
    if key is None:
        seen = set()
        return [x for x in items if not (x in seen or seen.add(x))]
    else:
        seen = set()
        return [x for x in items if not (x.key in seen or seen.add(x.key))]

