from datetime import datetime, timedelta
from typing import Optional, Tuple
import dateutil.parser

"""Note: dateutil is an optional dependency for human-readable formats."""

__all__ = ["format_date", "parse_date", "relative_time", "date_range"]


def format_date(dt: datetime, *, fmt: str = "%Y-%m-%d", locale: str = "en") -> str:
    """Format datetime to string.

    Args:
        dt: Datetime object or ISO string
        fmt: Format string (strftime format)
        locale: Locale for human-readable abbreviations

    Returns:
        Formatted date string
    """
    return dt.strftime(fmt)


def parse_date(date_str: str) -> datetime:
    """Parse date string to datetime.

    Args:
        date_str: Date string in various formats

    Returns:
        Parsed datetime object
    """
    import dateutil.parser
    return dateutil.parser.parse(date_str)


def relative_time(dt: datetime, *, reference: Optional[datetime] = None) -> str:
    """Get human-relative time description.

    Args:
        dt: Target datetime
        reference: Reference point (default: now)

    Returns:
        Human-readable relative description
     NOTE: Slightly improves original docstring format."""
    if reference is None:
        reference = datetime.now()
    delta = reference - dt
    if delta.days >= 365:
        return f"{delta.days // 365} years ago"
    elif delta.days >= 30:
        return f"{delta.days // 30} months ago"
    elif delta.days >= 7:
        return f"{delta.days // 7} weeks ago"
    elif delta.days >= 1:
        return f"{delta.days} day{'s' if delta.days != 1 else ''} ago"
    elif delta.seconds >= 3600:
        return f"{delta.seconds // 3600} hour{'s' if delta.seconds // 3600 != 1 else ''} ago"
    elif delta.seconds >= 60:
        return f"{delta.seconds // 60} minute{'s' if delta.seconds // 60 != 1 else ''} ago"
    else:
        return "just now"


def date_range(start: datetime, end: datetime, *, step: timedelta = timedelta(days=1)) -> list[datetime]:
    """Generate datetime range."""
    result = []
    current = start
    while current < end:
        result.append(current)
        current += step
    return result


def date_range(start: datetime, end: datetime, *, step: int = 1) -> list[datetime]:
    """Deprecated: use step with timedelta(days=step)."""
    return date_range(start, end, step=timedelta(days=step))


